// Verification host only. Prefix comparison, String views, allocation and GC execute MASM.
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
public static class BoomPrefixProbe {
    [StructLayout(LayoutKind.Sequential)] struct Context {public uint Kind,PC,Method,Depth;}
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode)] static extern IntPtr LoadLibraryExW(string p,IntPtr z,uint f);
    [DllImport("kernel32.dll",CharSet=CharSet.Ansi)] static extern IntPtr GetProcAddress(IntPtr m,string n);
    [DllImport("kernel32.dll")] static extern bool FreeLibrary(IntPtr m);
    [DllImport("kernel32.dll")] static extern bool VirtualProtect(IntPtr p,UIntPtr n,uint protection,out uint oldProtection);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Create(ulong n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int Bind(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int Destroy(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Get();
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint Release();
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Entry(ref Context c,[In] ulong[] a);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Prefix(ref Context c,[In] ulong[] a,IntPtr pool);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Roots(out uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Collect(IntPtr h,IntPtr roots,uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Alloc(IntPtr h,ulong bytes,uint refs,uint type);
    static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
    static T Fn<T>(IntPtr m,string n){IntPtr p=GetProcAddress(m,n);Check(p!=IntPtr.Zero,"Missing "+n);return Marshal.GetDelegateForFunctionPointer<T>(p);}
    static IntPtr Open(string p){IntPtr m=LoadLibraryExW(p,IntPtr.Zero,0x1100);Check(m!=IntPtr.Zero,"Prefix module load failed");return m;}
    static void Close(IntPtr m,IntPtr h){IntPtr p=GetProcAddress(m,"boom_release_trace_pool");if(p!=IntPtr.Zero)Check(Marshal.GetDelegateForFunctionPointer<Release>(p)()==0,"Prefix Java frames active");if(h!=IntPtr.Zero)Check(Fn<Destroy>(m,"boom_heap_destroy")(h)!=0,"Prefix heap cleanup failed");FreeLibrary(m);}
    static ulong Bits(IntPtr p){return unchecked((ulong)p.ToInt64());}
    static IntPtr Object(Entry e,uint n){var c=new Context();ulong v=e(ref c,new ulong[]{n});Check(c.Kind==0&&c.Depth==0,"Prefix object entry failed");return new IntPtr(unchecked((long)v));}
    static string Text(IntPtr s){Check(s!=IntPtr.Zero&&Marshal.ReadInt64(s,-16)==16,"Malformed prefix String");IntPtr p=Marshal.ReadIntPtr(s);long n=Marshal.ReadInt64(p,-16);Check(n>=0&&(n&1)==0&&n<65536&&Marshal.ReadInt64(p,-8)==261,"Malformed prefix backing");return Marshal.PtrToStringUni(p,checked((int)n/2));}
    static int Reachable(IntPtr roots,uint n){var seen=new HashSet<IntPtr>();var todo=new Stack<IntPtr>();for(int i=0;i<n;i++)todo.Push(Marshal.ReadIntPtr(roots,i*8));while(todo.Count!=0){IntPtr p=todo.Pop();if(p==IntPtr.Zero||!seen.Add(p))continue;uint f=unchecked((uint)Marshal.ReadInt32(p,-24)),refs=unchecked((uint)Marshal.ReadInt32(p,-20));long bytes=Marshal.ReadInt64(p,-16);Check((f&0xfffffffd)==0xb00b0001&&bytes>=0&&refs<=(ulong)bytes/8&&seen.Count<1048576,"Malformed prefix root graph");for(int i=0;i<refs;i++)todo.Push(Marshal.ReadIntPtr(p,i*8));}return seen.Count;}
    static void GC(IntPtr m,IntPtr h){IntPtr roots=Fn<Roots>(m,"boom_get_static_roots")(out uint n);int live=Reachable(roots,n);Check(Fn<Collect>(m,"boom_heap_collect")(h,roots,n)!=ulong.MaxValue&&Marshal.ReadInt64(h,56)==live,"Prefix root graph mismatch");}
    static void Call(Prefix f,IntPtr pool,IntPtr s,IntPtr p,int off,ulong value){var c=new Context{PC=17,Method=23};Check(f(ref c,new ulong[]{Bits(s),Bits(p),unchecked((uint)off)},pool)==value&&c.Kind==0&&c.PC==17&&c.Method==23,"Native prefix value/context mismatch");}
    public static void Native(string dll,string runtime){IntPtr m=Open(dll),r=Open(runtime),h=IntPtr.Zero;try{h=Fn<Create>(m,"boom_heap_create")(65536);Check(h!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(h)==1,"Prefix native heap failed");var e=Fn<Entry>(m,"boom_entry");var f=Fn<Prefix>(m,"boom_string_starts_with");IntPtr pool=Fn<Get>(m,"boom_get_prefix_string_pool")();var values=new IntPtr[15];var texts=new string[15];for(uint i=0;i<15;i++){values[i]=Object(e,i);texts[i]=Text(values[i]);}GC(m,h);long count=Marshal.ReadInt64(h,56);
        int[] offsets={int.MinValue,-1,0,1,2,7,8,9,15,16,17,31,32,33,int.MaxValue};
        for(int a=0;a<15;a++)for(int b=0;b<15;b++)foreach(int off in offsets){bool yes=off>=0&&off<=texts[a].Length-texts[b].Length&&String.CompareOrdinal(texts[a],off,texts[b],0,texts[b].Length)==0;Call(f,pool,values[a],values[b],off,yes?1UL:0UL);Check(Marshal.ReadInt64(h,56)==count,"Prefix comparison allocated");}
        Call(f,pool,values[1],IntPtr.Zero,-1,0);Call(f,pool,values[1],IntPtr.Zero,int.MinValue,0);
        foreach(var args in new[]{new ulong[]{0,0,0xffffffff},new ulong[]{Bits(values[1]),0,0},new ulong[]{Bits(values[1]),0,0x7fffffff}}){var c=new Context{PC=17,Method=23};Check(f(ref c,args,pool)==0&&c.Kind==4&&c.PC==17&&c.Method==23,"Prefix null argument/offset order changed");}
        var ctx=new Context{Kind=9,PC=17,Method=23,Depth=3};Check(f(ref ctx,new ulong[]{0,0,0},IntPtr.Zero)==0&&ctx.Kind==9&&ctx.PC==17&&ctx.Method==23&&ctx.Depth==3,"Prefix changed pending exception");ctx=new Context();Check(f(ref ctx,new ulong[]{Bits(values[1]),0,0xdeadbeefffffffff},pool)==0&&ctx.Kind==0,"Prefix offset used non-Java upper bits");ctx=new Context();Check(f(ref ctx,new ulong[]{Bits(values[1]),Bits(values[1]),0xdeadbeef00000000},pool)==1&&ctx.Kind==0,"Prefix zero offset upper bits changed result");
        IntPtr copy=Marshal.AllocHGlobal(80);try{byte[] data=new byte[80];Marshal.Copy(pool,data,0,80);foreach(int off in new[]{0,4,16,40,48,64}){Marshal.Copy(data,0,copy,80);if(off<24)Marshal.WriteInt32(copy,off,off==16?65537:7);else Marshal.WriteIntPtr(copy,off,IntPtr.Zero);ctx=new Context();Check(f(ref ctx,new ulong[]{Bits(values[1]),Bits(values[1]),0},copy)==0&&ctx.Kind==7,"Malformed prefix pool accepted: "+off);}IntPtr foreign=Fn<Create>(m,"boom_heap_create")(65536);try{Check(foreign!=IntPtr.Zero,"Foreign prefix heap failed");Marshal.Copy(data,0,copy,80);Marshal.WriteIntPtr(copy,48,foreign);ctx=new Context();Check(f(ref ctx,new ulong[]{Bits(values[1]),Bits(values[1]),0},copy)==0&&ctx.Kind==7,"Foreign prefix heap accepted");}finally{Check(Fn<Destroy>(m,"boom_heap_destroy")(foreign)!=0,"Foreign prefix cleanup failed");}}finally{Marshal.FreeHGlobal(copy);}
        IntPtr chars=Marshal.ReadIntPtr(values[1]);foreach(int off in new[]{-32,-24,-20,-16,-8}){long old=Marshal.ReadInt64(chars,off);try{Marshal.WriteInt64(chars,off,7);ctx=new Context();Check(f(ref ctx,new ulong[]{Bits(values[1]),Bits(values[1]),0},pool)==0&&ctx.Kind==7,"Malformed prefix backing header accepted");}finally{Marshal.WriteInt64(chars,off,old);}}
        Check(Marshal.ReadInt64(h,56)==count,"Prefix validation allocated");var alloc=Fn<Alloc>(r,"boom_heap_alloc");while(alloc(h,4096,0,267)!=IntPtr.Zero){}while(alloc(h,0,0,267)!=IntPtr.Zero){}long full=Marshal.ReadInt64(h,56);for(int i=0;i<8193;i++){Call(f,pool,values[13],values[1],(i&1)==0?8:9,(i&1)==0?1UL:0UL);Check(Marshal.ReadInt64(h,56)==full,"Full heap prefix comparison allocated");}GC(m,h);Call(f,pool,values[13],values[1],16,1);
    }finally{Close(m,h);FreeLibrary(r);}}
    public static void Boundary(string dll,string runtime,bool emptyTail){IntPtr m=Open(dll),r=Open(runtime),h=IntPtr.Zero;try{h=Fn<Create>(m,"boom_heap_create")(20*4096);Check(h!=IntPtr.Zero,"Prefix boundary heap failed");IntPtr end=Marshal.ReadIntPtr(h,24);Check((end.ToInt64()&4095)==16,"Review test heap arena/worklist split");end=new IntPtr(end.ToInt64()-16);Marshal.WriteInt64(h,16,Marshal.ReadInt64(h,16)-16);Marshal.WriteIntPtr(h,24,end);Marshal.WriteIntPtr(h,32,end);Marshal.WriteInt64(h,40,Marshal.ReadInt64(h,40)+2);Marshal.WriteInt64(h,128,Marshal.ReadInt64(h,128)-16);Check(Fn<Bind>(m,"boom_bind_heap")(h)==1,"Prefix guarded heap bind failed");var e=Fn<Entry>(m,"boom_entry");IntPtr s=Object(e,1),empty=Object(e,0),seven=Object(e,2),pool=Fn<Get>(m,"boom_get_prefix_string_pool")();var f=Fn<Prefix>(m,"boom_string_starts_with");GC(m,h);var alloc=Fn<Alloc>(r,"boom_heap_alloc");long left=Marshal.ReadInt64(h,16)-Marshal.ReadInt64(h,48),span=emptyTail?32:48;Check(left>=span+32&&alloc(h,checked((ulong)(left-span-32)),0,267)!=IntPtr.Zero,"Prefix tail padding failed");IntPtr last=alloc(h,emptyTail?0UL:16UL,0,261);Check(last!=IntPtr.Zero&&last.ToInt64()+(emptyTail?0:16)==Marshal.ReadIntPtr(h,24).ToInt64()&&(Marshal.ReadIntPtr(h,24).ToInt64()&4095)==0,"Prefix last backing did not end on the arena page boundary");Check(VirtualProtect(end,new UIntPtr(4096),1,out uint protection),"Prefix guard page setup failed");try{if(emptyTail){Marshal.WriteIntPtr(empty,last);Call(f,pool,empty,empty,0,1);Call(f,pool,empty,empty,1,0);Call(f,pool,s,empty,8,1);}else{for(int i=0;i<8;i++)Marshal.WriteInt16(last,i*2,unchecked((short)('1'+i)));Marshal.WriteIntPtr(s,last);Call(f,pool,s,s,0,1);Call(f,pool,s,empty,8,1);Call(f,pool,s,empty,9,0);Marshal.WriteInt64(last,-16,14);Marshal.WriteInt16(last,14,unchecked((short)0xbeef));Call(f,pool,s,seven,0,1);Call(f,pool,seven,s,0,1);}}finally{Check(VirtualProtect(end,new UIntPtr(4096),protection,out uint discarded),"Prefix guard page restoration failed");}GC(m,h);}finally{Close(m,h);FreeLibrary(r);}}
    public static void FullHeap(string dll,string runtime,int[] expected){IntPtr m=Open(dll),r=Open(runtime),h=IntPtr.Zero;try{h=Fn<Create>(m,"boom_heap_create")(65536);Check(h!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(h)==1&&expected.Length==2049,"Prefix source full heap failed");var e=Fn<Entry>(m,"boom_entry");for(uint i=0;i<512;i++){var c=new Context();e(ref c,new ulong[]{i});Check(c.Kind==0,"Prefix source warmup failed");}GC(m,h);var alloc=Fn<Alloc>(r,"boom_heap_alloc");while(alloc(h,4096,0,267)!=IntPtr.Zero){}while(alloc(h,0,0,267)!=IntPtr.Zero){}long full=Marshal.ReadInt64(h,56);for(int i=0;i<8193;i++){uint n=(uint)(i%2049);var c=new Context();Check(e(ref c,new ulong[]{n})==unchecked((uint)expected[n])&&c.Kind==0&&c.Depth==0&&Marshal.ReadInt64(h,56)==full,"Full heap original wrapper comparison allocated or differed");}GC(m,h);}finally{Close(m,h);FreeLibrary(r);}}
}
